#include <iostream>
#include <string_view>

// Self-referential struct blueprint
struct Node {
    int id;
    std::string_view name;
    Node* nextPtr; // Pointer to same struct type is valid
};

int main() {
    // Instantiating nodes (C++ does not require 'struct Node')
    Node tail{2, "TailNode", nullptr};
    Node head{1, "HeadNode", &tail};

    std::cout << "Node 1: [ID=" << head.id << ", Name=" << head.name << "]\n";
    std::cout << "Node 2 via pointer: [ID=" << head.nextPtr->id 
              << ", Name=" << head.nextPtr->name << "]\n";

    return 0;
}

#include <iostream>

struct Example {
    char c; // 1 byte
    // 3 bytes of compiler padding inserted here on typical 32/64-bit systems
    int i;  // 4 bytes
};

// Member-by-member comparison function (safe idiomatic approach in C++17)
bool areEqual(const Example& lhs, const Example& rhs) {
    return lhs.c == rhs.c && lhs.i == rhs.i;
}

int main() {
    Example s1{'A', 100};
    Example s2 = s1; // Valid assignment of same struct type

    std::cout << "sizeof(char): " << sizeof(char) << " byte\n";
    std::cout << "sizeof(int): " << sizeof(int) << " bytes\n";
    std::cout << "sizeof(Example): " << sizeof(Example) << " bytes\n";
    std::cout << "Are s1 and s2 memberwise equal? " << (areEqual(s1, s2) ? "yes" : "no") << '\n';

    return 0;
}
